'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='han-question-study-v1';
let saved; try {saved=JSON.parse(localStorage.getItem(KEY)||'null')} catch {}
let records=Array.isArray(saved?.records)?saved.records:[], wrong=new Set(Array.isArray(saved?.wrong)?saved.wrong:[]);
let tab='practice', category='전체', type='all', count=10, session=null;
const categories=['전체','소프트웨어','데이터베이스','운영체제','네트워크','보안','프로그래밍','계산'];
const typeName=t=>t==='choice'?'객관식':t==='short'?'단답형':'혼합';
const dateKey=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function persist(){try{localStorage.setItem(KEY,JSON.stringify({records,wrong:[...wrong]}));}catch{toast('기록을 저장할 수 없습니다. 브라우저 저장 설정을 확인하세요.')}badge()}
function badge(){$('#wrong-badge').textContent=wrong.size}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function pool(){return QUESTIONS.filter(q=>(category==='전체'||q.category===category)&&(type==='all'||q.type===type))}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function nav(){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));badge()}
function setTab(t){if(session&&!session.done){toast('진행 중인 문제를 마치거나 학습을 종료해주세요.');return}tab=t;nav();render()}
function render(){nav();if(tab==='wrong')return renderWrong();if(tab==='history')return renderHistory();renderHome()}
function renderHome(){session=null;const today=records.filter(r=>r.day===dateKey());const n=today.reduce((a,r)=>a+r.total,0), correct=today.reduce((a,r)=>a+r.correct,0);const available=pool().length;
$('#main').innerHTML=`<section class="intro"><div><div class="eyebrow">정보처리기사 · 필기 & 실기</div><h1>정보처리기사 문제 연습</h1><p>과목과 유형을 고르고 문제를 풀어보세요.<br>정답과 해설을 확인하고, 틀린 문제는 다시 연습할 수 있어요.</p></div><div class="intro-art" aria-hidden="true"><div class="paper"><div></div><div></div><div></div><span>✓</span></div></div></section><div class="grid"><section class="card"><div class="card-title"><span class="tiny-icon" aria-hidden="true">☷</span><h2>어떤 문제를 풀어볼까요?</h2></div><div class="field"><div class="field-label">학습 범위<small>한 과목에 집중해도 좋아요</small></div><div class="pills">${categories.map(c=>`<button class="pill ${c===category?'selected':''}" data-cat="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div></div><div class="field"><div class="field-label">문제 유형<small>실기 대비는 단답형을 추천해요</small></div><div class="segmented">${[['all','혼합 문제'],['short','단답형'],['choice','객관식']].map(([t,l])=>`<button class="segment ${type===t?'selected':''}" data-type="${t}" aria-pressed="${type===t}">${l}</button>`).join('')}</div></div><div class="setting-row"><div class="field"><label class="field-label" for="count">문제 수</label><select id="count" class="select">${[5,10,20].map(n=>`<option value="${n}" ${count===n?'selected':''}>${n}문제</option>`).join('')}</select></div><div class="field"><div class="field-label">출제 방식</div><div class="select" style="background:#fafafa;color:#737373">무작위 · 중복 없이</div></div></div><div class="start-info"><span>준비된 문제 ${available}개</span><span>약 ${Math.min(count,available)}분 학습</span></div><button id="start" class="btn full start-btn" ${available?'':'disabled'}><span>${available?'문제 풀기 시작':'해당 유형의 문제가 없어요'}</span><span aria-hidden="true">→</span></button><p class="footnote">${available&&available<count?`선택 범위에 있는 ${available}문제 모두 출제합니다.`:'정답 확인 후, 해설까지 천천히 읽어보세요.'}</p></section><aside class="side"><section class="card"><h2>오늘의 학습</h2><div class="stats"><div><div class="stat-label">완료한 문제</div><div class="stat-number">${n}<small>문제</small></div></div><div><div class="stat-label">정답률</div><div class="stat-number">${n?Math.round(correct/n*100):0}<small>%</small></div></div></div><div class="rule"></div><div class="side-bottom"><span>다시 볼 오답</span><span>${wrong.size}문제</span></div></section><section class="card note-card"><span class="mini-label">STUDY NOTE</span><h3>정답보다 중요한 건<br>왜 그런지 이해하는 것.</h3><p>틀린 문제는 오답노트에 모아둘게요.<br>다시 풀고, 내 것으로 만들어 보세요.</p><button class="inline-link" id="go-wrong">오답노트 보기 →</button></section><div class="source-teaser"><strong>내 자료로 만드는 공부 습관</strong><br>첨부한 요약·계산·키워드 자료의 핵심 개념을<br>${QUESTIONS.length}개의 연습 문제로 구성했어요.</div></aside></div><div class="bottom-note"><span class="dot"></span>학습 기록은 이 브라우저에 자동으로 저장됩니다.</div>`;
document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;renderHome()});document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;renderHome()});$('#count').onchange=e=>{count=Number(e.target.value);renderHome()};$('#start').onclick=()=>start(pool(),category+' · '+typeName(type),count);$('#go-wrong').onclick=()=>setTab('wrong')}
function start(items,label,n){if(!items.length)return toast('출제할 문제가 없습니다.');session={questions:shuffle(items).slice(0,n),label,index:0,results:[],checked:false,selection:null,started:Date.now(),done:false};tab='practice';nav();renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function current(){return session.questions[session.index]}
function renderQuestion(){const q=current();session.checked=false;session.selection=null;$('#main').innerHTML=`<div class="quiz-wrap"><div class="quiz-top"><button id="exit" class="btn text">← 학습 종료</button><span>${esc(session.label)}</span><span>${session.index+1} / ${session.questions.length}</span></div><div class="progress" role="progressbar" aria-label="학습 진행률" aria-valuemin="0" aria-valuemax="${session.questions.length}" aria-valuenow="${session.index}"><div style="width:${session.index/session.questions.length*100}%"></div></div><section class="card question-card"><div class="tags"><span>${esc(q.category)}</span><span>${typeName(q.type)}</span></div><div class="q-number">QUESTION ${String(session.index+1).padStart(2,'0')}</div><h2>${esc(q.prompt)}</h2><div id="answer-area">${q.type==='choice'?`<div class="choice-list">${q.choices.map((c,i)=>`<button class="choice" data-choice="${i}" aria-pressed="false"><span class="choice-num">${i+1}</span><span>${esc(c)}</span></button>`).join('')}</div>`:`<label for="answer" class="field-label">나의 답안</label><input id="answer" class="answer-input" placeholder="정답을 입력해 주세요" autocomplete="off"><p class="muted" style="margin-bottom:0">용어는 한글 또는 영어로 입력할 수 있어요.</p>`}</div><div id="feedback" aria-live="polite"></div><div class="quiz-actions"><button id="reveal" class="btn text">모르겠어요 · 정답 보기</button><button id="check" class="btn">정답 확인 <span>→</span></button></div></section><p class="footnote">${q.type==='choice'?'선택 후 정답 확인을 눌러주세요.':'Enter 키로 정답을 확인할 수 있어요.'}</p></div>`;
$('#exit').onclick=()=>{if(session.results.length)finish(true);else{session=null;renderHome()}};
document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(session.checked)return;session.selection=Number(b.dataset.choice);document.querySelectorAll('[data-choice]').forEach(el=>{const on=el===b;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',on)})});$('#check').onclick=()=>check(false);$('#reveal').onclick=()=>check(true);if($('#answer'))$('#answer').onkeydown=e=>{if(e.key==='Enter')check(false)}}
function normalize(s){return String(s).normalize('NFKC').toLowerCase().replace(/[\s\-_.，,;:·()]/g,'')}
function check(reveal){if(session.checked)return;const q=current();const input=q.type==='choice'?(session.selection===null?'':q.choices[session.selection]):$('#answer').value.trim();if(!reveal&&!input){toast('답안을 입력하거나 선택해 주세요.');$('#answer')?.focus();return}const correct=!reveal&&(q.type==='choice'?input===q.answer:q.aliases.some(a=>normalize(a)===normalize(input)));session.checked=true;session.results.push({id:q.id,answer:input,correct});if(correct)wrong.delete(q.id);else wrong.add(q.id);persist();if($('#answer'))$('#answer').disabled=true;document.querySelectorAll('[data-choice]').forEach(b=>{b.disabled=true;const val=q.choices[Number(b.dataset.choice)];if(val===q.answer)b.classList.add('correct');else if(val===input)b.classList.add('incorrect')});showFeedback();$('#check').textContent=session.index===session.questions.length-1?'학습 결과 보기 →':'다음 문제 →';$('#check').onclick=()=>{if(session.index===session.questions.length-1)finish();else{session.index++;renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}};$('#reveal').style.visibility='hidden'}
function showFeedback(){const q=current(),r=session.results.at(-1),source=SOURCES.find(s=>s.id===`source-${q.source}`);$('#feedback').innerHTML=`<div class="feedback ${r.correct?'':'wrong'}"><h3>${r.correct?'✓ 정답이에요!':'다음에는 기억할 수 있어요.'}</h3><p><strong>정답 · ${esc(q.answer)}</strong></p>${r.answer&&!r.correct?`<p class="muted">나의 답 · ${esc(r.answer)}</p>`:''}<p>${esc(q.explanation)}</p><p class="source-ref">참고 · ${esc(source?.name||'첨부 학습자료')} · PDF ${q.page}쪽<br>핵심 개념을 바탕으로 구성한 연습 문제</p>${!r.correct&&r.answer&&q.type==='short'?'<button id="self-correct">표현이 다르지만 맞는 답이에요</button>':''}</div>`;if($('#self-correct'))$('#self-correct').onclick=()=>{r.correct=true;wrong.delete(q.id);persist();showFeedback();toast('정답으로 반영했어요.')}}
function finish(partial=false){session.done=true;const total=session.results.length,correct=session.results.filter(r=>r.correct).length;if(total){records.unshift({id:Date.now(),day:dateKey(),at:new Date().toISOString(),label:session.label,total,correct,partial,seconds:Math.round((Date.now()-session.started)/1000)});records=records.slice(0,100);persist()}renderResult(partial)}
function renderResult(partial){const n=session.results.length,c=session.results.filter(r=>r.correct).length;$('#main').innerHTML=`<div class="quiz-wrap"><section class="card result"><div class="eyebrow">${partial?'STUDY SAVED':'WELL DONE'}</div><h1>${partial?'푼 문제까지 기록했어요.':'오늘도 한 걸음 더 가까이.'}</h1><p>${esc(session.label)} · ${n}문제 학습</p><div class="big-score">${n?Math.round(c/n*100):0}<span style="font-size:24px;letter-spacing:0">%</span></div><p>${n}문제 중 ${c}문제 정답<br>${n-c?'틀린 문제는 오답노트에서 다시 만나요.':'잘했어요. 다음 문제도 차근차근 풀어봐요.'}</p><div class="result-actions"><button class="btn" id="again">새 문제 풀기 →</button><button class="btn secondary" id="result-wrong">오답노트 보기</button></div></section><section class="card result-list" style="padding:10px 0">${session.results.map(r=>{const q=QUESTIONS.find(q=>q.id===r.id);return `<div class="result-row ${r.correct?'':'bad'}"><b>${r.correct?'✓':'↺'}</b><div>${esc(q.prompt)}<br><span class="muted">정답 · ${esc(q.answer)}</span></div></div>`}).join('')}</section></div>`;$('#again').onclick=()=>{session=null;renderHome()};$('#result-wrong').onclick=()=>{session=null;setTab('wrong')};window.scrollTo({top:0,behavior:'smooth'})}
function renderWrong(){const items=QUESTIONS.filter(q=>wrong.has(q.id));$('#main').innerHTML=`<h1 class="page-title">다시 보면, 내 것이 돼요.</h1><p class="page-sub">틀린 문제 ${items.length}개를 모았어요. 다시 풀어 정답을 맞히면 오답노트에서 빠집니다.</p>${items.length?`<div class="list-toolbar"><span class="muted">정답은 문제를 다시 풀 때 확인해 보세요.</span><button class="btn" id="review-all">오답 ${items.length}문제 다시 풀기 →</button></div>${items.map(q=>`<article class="card wrong-item"><div class="body"><div class="tags"><span>${esc(q.category)}</span><span>${typeName(q.type)}</span></div><h3>${esc(q.prompt)}</h3></div><button class="btn secondary" data-review="${q.id}">다시 풀기</button></article>`).join('')}`:`<section class="card empty"><div class="empty-symbol">✓</div><h2>아직 모아둔 오답이 없어요.</h2><p>문제를 풀며 헷갈렸던 개념을 이곳에 모아둘게요.<br>가볍게 첫 학습을 시작해 보세요.</p><button class="btn" id="empty-start">문제 풀기 →</button></section>`}`;if($('#review-all'))$('#review-all').onclick=()=>start(items,'오답 복습',items.length);document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>start(items.filter(q=>q.id===b.dataset.review),'오답 복습',1));if($('#empty-start'))$('#empty-start').onclick=()=>setTab('practice')}
function renderHistory(){const total=records.reduce((a,r)=>a+r.total,0),correct=records.reduce((a,r)=>a+r.correct,0);$('#main').innerHTML=`<h1 class="page-title">쌓이고 있는 나의 공부.</h1><p class="page-sub">${records.length}번의 학습 · 총 ${total}문제 · 정답률 ${total?Math.round(correct/total*100):0}%</p>${records.length?records.map(r=>`<article class="card history-item"><div><strong>${esc(r.label)}</strong><small>${new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(r.at))} · ${r.total}문제${r.partial?' · 중간 종료':''}</small></div><div class="score">${Math.round(r.correct/r.total*100)}<small>%</small><small style="display:block;text-align:right">${r.correct} / ${r.total} 정답</small></div></article>`).join(''):`<section class="card empty"><div class="empty-symbol">☷</div><h2>첫 번째 기록을 기다리고 있어요.</h2><p>학습을 마치면 날짜와 정답률을 기록해 드릴게요.</p><button class="btn" id="history-start">첫 학습 시작 →</button></section>`}<div class="bottom-note"><span class="dot"></span>이 브라우저의 기록입니다. 다른 기기와는 동기화되지 않습니다.</div>`;if($('#history-start'))$('#history-start').onclick=()=>setTab('practice')}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();setTab('practice')};$('#source-link').onclick=()=>{$('#source-list').innerHTML=SOURCES.map(s=>`<div class="source-entry">${esc(s.name)}<small>${s.pages}쪽 · 개념 참고 자료</small></div>`).join('');$('#sources').showModal()};$('#close-sources').onclick=()=>$('#sources').close();$('#sources').onclick=e=>{if(e.target===$('#sources')){const r=$('#sources').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#sources').close()}};render();
